0)::numeric) AND (target_weight <= (1)::numeric)))"},{"name":"portfolio_trades_user_id_symbol_signal_date_key","definition":"UNIQUE (user_id, symbol, signal_date)"}]},{"acl":["postgres=arwdDxtm/postgres","service_role=arwdDxtm/postgres","authenticated=arw/postgres"],"rls":true,"owner":"postgres","table":"us_actual_portfolio_ledgers","schema":"public","columns":[{"name":"user_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"name":"revision","type":"integer","default":"1","identity":"","not_null":true,"generated":""},{"name":"payload","type":"jsonb","default":null,"identity":"","not_null":true,"generated":""},{"name":"updated_at","type":"timestamp with time zone","default":"now()","identity":"","not_null":true,"generated":""}],"triggers":[{"name":"reject_website_truncate","enabled":"O","definition":"CREATE TRIGGER reject_website_truncate BEFORE TRUNCATE ON public.us_actual_portfolio_ledgers FOR EACH STATEMENT EXECUTE FUNCTION cloudtrend_ledger_private.sync_website_document()"},{"name":"sync_unified_actual","enabled":"O","definition":"CREATE TRIGGER sync_unified_actual AFTER INSERT OR DELETE OR UPDATE ON public.us_actual_portfolio_ledgers FOR EACH ROW EXECUTE FUNCTION cloudtrend_ledger_private.sync_website_document()"}],"force_rls":false,"constraints":[{"name":"us_actual_portfolio_ledgers_payload_check","definition":"CHECK ((jsonb_typeof(payload) = 'object'::text))"},{"name":"us_actual_portfolio_ledgers_pkey","definition":"PRIMARY KEY (user_id)"},{"name":"us_actual_portfolio_ledgers_revision_check","definition":"CHECK ((revision > 0))"},{"name":"us_actual_portfolio_ledgers_user_id_fkey","definition":"FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE"}]},{"acl":["postgres=arwdDxtm/postgres","authenticated=rm/postgres","service_role=arwdDxtm/postgres"],"rls":true,"owner":"postgres","table":"us_portfolio_snapshots","schema":"public","columns":[{"name":"user_id","type":"uuid","default":null,"identity":"","not_null":true,"gene