-- Exact source tuples protect BOTH source and event-version insertion, including service_role.
INSERT INTO cloudtrend_legacy_archive.tombstones
 SELECT x.scope_table,r.key,cloudtrend_legacy_archive.hash(r.row_data) FROM cloudtrend_legacy_archive.rows r CROSS JOIN (VALUES('public.ledger_event_sources'),('public.ledger_event_versions')) x(scope_table) WHERE r.table_name='public.ledger_event_sources';
-- Identity-level US strategy and beta-series retirement protects future dates/keys.
INSERT INTO cloudtrend_legacy_archive.tombstones
 SELECT x.scope_table,r.key,r.row_hash FROM cloudtrend_legacy_archive.rows r CROSS JOIN (VALUES('public.us_strategy_registry'),('public.us_portfolio_snapshots'),('public.us_portfolio_trades')) x(scope_table) WHERE r.table_name='public.us_strategy_registry';
INSERT INTO cloudtrend_legacy_archive.tombstones
 SELECT x.scope_table,r.key,r.row_hash FROM cloudtrend_legacy_archive.rows r CROSS JOIN (VALUES('public.ledger_model_series'),('public.ledger_model_sessions')) x(scope_table) WHERE r.table_name='public.ledger_model_series';
INSERT INTO cloudtrend_legacy_archive.tombstones
 SELECT table_name,key||jsonb_build_object('user_id',row_data->'user_id'),row_hash FROM cloudtrend_legacy_archive.rows WHERE table_name IN ('public.portfolio_trades','public.portfolio_signal_log');
-- Also guard KR unique economic identity even if a regenerated UUID is supplied.
INSERT INTO cloudtrend_legacy_archive.tombstones
 SELECT table_name,jsonb_build_object('user_id',row_data->'user_id','symbol',row_data->'symbol','signal_date',row_data->'signal_date'),row_hash FROM cloudtrend_legacy_archive.rows WHERE table_name='public.portfolio_trades';
DO $$ DECLARE t text; BEGIN
 FOR t IN SELECT DISTINCT scope_table FROM cloudtrend_legacy_archive.tombstones LOOP
  EXECUTE format('CREATE TRIGGER reject_retired_legacy BEFORE INSERT OR UPDATE ON %s FOR EACH ROW EXECUTE FUNCTION cloudtrend_legacy_archive.reject_retired()',t);
  EXECUTE format('ALTER TABLE %s ENABLE ALWAYS TRIGGER reject_retired_legacy',t);
 END LOOP;
END $$;
-- Disable only reviewed mutation barriers, never ALL/USER/foreign-key triggers.
ALTER TABLE public.ledger_event_versions DISABLE TRIGGER immutable_history;
ALTER TABLE public.ledger_event_sources DISABLE TRIGGER immutable_history;
ALTER TABLE public.ledger_model_sessions DISABLE TRIGGER immutable_history;
ALTER TABLE public.ledger_model_series DISABLE TRIGGER immutable_history;
ALTER TABLE public.portfolio_ledgers DISABLE TRIGGER sync_unified_actual;
ALTER TABLE public.us_actual_portfolio_ledgers DISABLE TRIGGER sync_unified_actual;
DO $$
DECLARE t text; r record; doc record; p jsonb; old_ids jsonb; n int;
BEGIN
 -- Descending revisions/dates satisfy immediate self-referential foreign keys.
 FOR t IN SELECT unnest(ARRAY['public.ledger_event_versions','public.ledger_event_sources','public.ledger_model_sessions','public.ledger_model_series','public.us_portfolio_trades','public.us_portfolio_snapshots','public.us_strategy_registry','public.portfolio_signal_log','public.portfolio_trades']) LOOP
  FOR r IN SELECT key,row_data FROM cloudtrend_legacy_archive.rows WHERE table_name=t ORDER BY (row_data->>'revision')::int DESC NULLS LAST,row_data->>'session_date' DESC NULLS LAST LOOP
   EXECUTE format('DELETE FROM %s s WHERE to_jsonb(s) @> $1 AND s.user_id=$2::uuid %s',t,CASE WHEN t IN ('public.ledger_event_sources','public.ledger_event_versions') THEN 'AND s.book=''ACTUAL'' AND s.book_id=''ACTUAL''' ELSE '' END) USING r.key,r.row_data->>'user_id';
   GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'Delete count drift'; END IF;
  END LOOP;
 END LOOP;
 FOR doc IN SELECT * FROM cloudtrend_legacy_archive.rows WHERE table_name IN ('public.portfolio_ledgers','public.us_actual_portfolio_ledgers') LOOP
  IF doc.table_name='public.portfolio_ledgers' AND cloudtrend_legacy_archive.hash((doc.row_data->'payload')-'executions')<>'06056ee4c7b8d1f9b8a937dbee353e8c204f1d35eb295d0c0f2c12f99182d92b' THEN RAISE EXCEPTION 'Preserved metadata baseline drift'; END IF;
  IF doc.table_name='public.us_actual_portfolio_ledgers' AND cloudtrend_legacy_archive.hash((doc.row_data->'payload')-'executions')<>'e0ea95e5fb489fa77de6af6114b63de2b68de04900f272ce412211d7ea032b6a' THEN RAISE EXCEPTION 'Preserved metadata baseline drift'; END IF;
  SELECT jsonb_agg(key->'source_record_id') INTO old_ids FROM cloudtrend_legacy_archive.rows WHERE table_name='public.ledger_event_sources' AND key->>'source_system'=split_part(doc.table_name,'.',2);
  IF old_ids IS NULL THEN RAISE EXCEPTION 'Missing approved execution IDs'; END IF;
  SELECT coalesce(jsonb_agg(e.value ORDER BY e.ordinality),'[]'::jsonb) INTO p FROM jsonb_array_elements(doc.row_data->'payload'->'executions') WITH ORDINALITY e WHERE NOT old_ids ? (e.value->>'id');
  IF jsonb_array_length(doc.row_data->'payload'->'executions')-jsonb_array_length(p)<>jsonb_array_length(old_ids) THEN RAISE EXCEPTION 'Document/source ID mismatch'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(old_ids) id WHERE ((doc.row_data->'payload')-'executions')::text LIKE '%'||id||'%') THEN RAISE EXCEPTION 'Retired execution referenced by preserved metadata; manual review required'; END IF;
  p:=jsonb_set(doc.row_data->'payload','{executions}',p,false);
  IF (p-'executions') IS DISTINCT FROM ((doc.row_data->'payload')-'executions') THEN RAISE EXCEPTION 'Preserved payload keys changed'; END IF;
  EXECUTE format('UPDATE %s s SET payload=$1,revision=revision+1 WHERE to_jsonb(s) @> $2',doc.table_name) USING p,doc.key;
  PERFORM cloudtrend_ledger_private.validate_document(p,split_part(doc.table_name,'.',2));
  PERFORM cloudtrend_ledger_private.assert_reconciled((doc.row_data->>'user_id')::uuid,split_part(doc.table_name,'.',2),p);
  UPDATE cloudtrend_ledger_private.bridge_documents SET document_revision=(doc.row_data->>'revision')::int+1,document_hash=cloudtrend_ledger_private.json_hash(p),ledger_hash=cloudtrend_ledger_private.source_hash((doc.row_data->>'user_id')::uuid,split_part(doc.table_name,'.',2)) WHERE user_id=(doc.row_data->>'user_id')::uuid AND source_system=split_part(doc.table_name,'.',2);
 END LOOP;
END $$;
ALTER TABLE public.ledger_event_versions ENABLE TRIGGER immutable_history;
ALTER TABLE public.ledger_event_sources ENABLE TRIGGER immutable_history;
ALTER TABLE public.ledger_model_sessions ENABLE TRIGGER immutable_history;
ALTER TABLE public.ledger_model_series ENABLE TRIGGER immutable_history;
ALTER TABLE public.portfolio_ledgers ENABLE TRIGGER sync_unified_actual;
ALTER TABLE public.us_actual_portfolio_ledgers ENABLE TRIGGER sync_unified_actual;
DO $$ DECLARE t jsonb; a jsonb; h text; BEGIN
 FOR t IN SELECT x.value FROM cloudtrend_legacy_archive.manifest m,jsonb_array_elements(m.value->'targets') x WHERE m.id='retirement' LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY to_jsonb(s)::text),''[]''::jsonb) FROM %s s WHERE EXISTS (SELECT 1 FROM jsonb_array_elements($1) k WHERE to_jsonb(s) @> k)',t->>'table_name') INTO a USING t->'keys';
  IF t->>'operation'='REMOVE' AND a<>'[]'::jsonb THEN RAISE EXCEPTION 'Retirement incomplete'; END IF;
  EXECUTE format('SELECT cloudtrend_legacy_archive.hash(coalesce(jsonb_agg(to_jsonb(s) ORDER BY to_jsonb(s)::text),''[]''::jsonb)) FROM %s s WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements($1) k WHERE to_jsonb(s) @> k)',t->>'table_name') INTO h USING t->'keys';
  IF h IS DISTINCT FROM (SELECT hash FROM pg_temp.preserved_before WHERE table_name=t->>'table_name') THEN RAISE EXCEPTION 'Unselected rows changed'; END IF;
  INSERT INTO cloudtrend_legacy_archive.poststate VALUES(t->>'table_name',a,h);
 END LOOP;
END $$;
-- Seal append as well as update/delete/truncate after both snapshots are complete.
DO $$ DECLARE t text; r record; BEGIN
 FOR t IN SELECT tablename FROM pg_catalog.pg_tables WHERE schemaname='cloudtrend_legacy_archive' LOOP
  EXECUTE format('CREATE TRIGGER archive_sealed BEFORE INSERT ON cloudtrend_legacy_archive.%I FOR EACH STATEMENT EXECUTE FUNCTION cloudtrend_legacy_archive.reject_mutation()',t);
 END LOOP;
 -- Revoke every inherited direct grant on NEW archive objects, not just known app roles.
 FOR r IN SELECT c.oid,n.nspname,c.relname,x.grantee FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL pg_catalog.aclexplode(c.relacl) x WHERE n.nspname='cloudtrend_legacy_archive' AND x.grantee<>c.relowner LOOP
  EXECUTE format('REVOKE ALL ON TABLE %I.%I FROM %s',r.nspname,r.relname,CASE WHEN r.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(r.grantee)) END);
 END LOOP;
 FOR r IN SELECT p.oid,x.grantee FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL pg_catalog.aclexplode(p.proacl) x WHERE n.nspname='cloudtrend_legacy_archive' AND x.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %s',r.oid::regprocedure,CASE WHEN r.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(r.grantee)) END);
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='cloudtrend_legacy_archive' AND c.relkind='r' AND (NOT c.relrowsecurity OR pg_get_userbyid(c.relowner)<>'postgres')) THEN RAISE EXCEPTION 'Archive ownership/RLS mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL pg_catalog.aclexplode(c.relacl) x WHERE n.nspname='cloudtrend_legacy_archive' AND x.grantee<>c.relowner) THEN RAISE EXCEPTION 'Archive ACL leak'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL pg_catalog.aclexplode(p.proacl) x WHERE n.nspname='cloudtrend_legacy_archive' AND x.grantee<>p.proowner) THEN RAISE EXCEPTION 'Archive function ACL leak'; END IF;
END $$;

